import { BellIcon, MagnifyingGlassIcon } from '@phosphor-icons/react';
import { ActionIcon, AppShell, Group, Stack, Text, TextInput, Title } from '@mantine/core';
import { useHeadroom } from '@mantine/hooks';
import { MantineLogo } from '@mantinex/mantine-logo';
import { OrdersTable } from './OrdersTable';
import { UserMenu } from './UserMenu';
import classes from './Headroom.module.css';

export function Headroom() {
  const { pinned } = useHeadroom({ fixedAt: 120 });

  return (
    <AppShell
      header={{ height: 60, collapsed: !pinned, offset: false }}
      padding={{ base: 'md', sm: 'xl' }}
    >
      <AppShell.Header>
        <Group h="100%" px="md" justify="space-between">
          <MantineLogo size={28} />

          <Group>
            <TextInput
              placeholder="Search"
              leftSection={<MagnifyingGlassIcon size={16} />}
              visibleFrom="sm"
              w={240}
            />
            <ActionIcon
              variant="default"
              size="lg"
              aria-label="Notifications"
              title="Notifications"
            >
              <BellIcon size={18} />
            </ActionIcon>
            <UserMenu />
          </Group>
        </Group>
      </AppShell.Header>

      <AppShell.Main className={classes.main} pt="var(--app-shell-header-height)">
        <Stack gap="lg" pt={{ base: 'md', sm: 'xl' }}>
          <div>
            <Title order={2} c="var(--mantine-color-bright)">
              Orders
            </Title>
            <Text size="sm">All orders placed in your store</Text>
          </div>
          <OrdersTable />
        </Stack>
      </AppShell.Main>
    </AppShell>
  );
}

import { Badge, Surface, Table, Title } from '@mantine/core';
import { OrderStatus, orders } from './data';

const statusColors: Record<OrderStatus, string> = {
  Paid: 'green',
  Pending: 'yellow',
  Refunded: 'red',
};

export function OrdersTable() {
  const rows = orders.map((order) => (
    <Table.Tr key={order.id}>
      <Table.Td>{order.id}</Table.Td>
      <Table.Td>{order.customer}</Table.Td>
      <Table.Td>{order.date}</Table.Td>
      <Table.Td>
        <Badge color={statusColors[order.status]}>{order.status}</Badge>
      </Table.Td>
      <Table.Td ta="right">{order.amount}</Table.Td>
    </Table.Tr>
  ));

  return (
    <Surface level={0} withBorder>
      <Title order={3} fz="md" p="md" c="var(--mantine-color-bright)">
        All orders
      </Title>
      <Table.ScrollContainer minWidth={500}>
        <Table verticalSpacing="sm" horizontalSpacing="md">
          <Table.Thead>
            <Table.Tr>
              <Table.Th>Order</Table.Th>
              <Table.Th>Customer</Table.Th>
              <Table.Th>Date</Table.Th>
              <Table.Th>Status</Table.Th>
              <Table.Th ta="right">Amount</Table.Th>
            </Table.Tr>
          </Table.Thead>
          <Table.Tbody>{rows}</Table.Tbody>
        </Table>
      </Table.ScrollContainer>
    </Surface>
  );
}

export type OrderStatus = 'Paid' | 'Pending' | 'Refunded';

export interface Order {
  id: string;
  customer: string;
  date: string;
  amount: string;
  status: OrderStatus;
}

const customers = [
  'Olivia Martin',
  'Jackson Lee',
  'Isabella Nguyen',
  'William Kim',
  'Sofia Davis',
  'Liam Brown',
  'Emma Wilson',
  'Noah Garcia',
];

const amounts = ['$1,250.00', '$320.00', '$89.90', '$2,400.00', '$145.50', '$560.00', '$780.00'];

const statuses: OrderStatus[] = ['Paid', 'Pending', 'Paid', 'Paid', 'Refunded', 'Pending'];

const formatDate = (daysAgo: number) =>
  new Date(2026, 9, 14 - daysAgo).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });

export const orders: Order[] = Array.from({ length: 40 }, (_, index) => ({
  id: `#${4821 - index}`,
  customer: customers[index % customers.length],
  date: formatDate(Math.floor(index / 3)),
  amount: amounts[index % amounts.length],
  status: statuses[index % statuses.length],
}));
